#!/usr/bin/env python3
"""Generate ENSDF G-records for 1977DA02.ens (34Cl).
Prints all G-records grouped by level block (Ei).
Usage: python gen_g_records.py
"""
from decimal import Decimal

NUCID = " 34CL"

def calc_eg(ei, ef):
    """Calculate Eg = Ei - Ef using Decimal for exact arithmetic."""
    return Decimal(str(ei)) - Decimal(str(ef))

def make_g_record(eg, ri, dri="", q=" "):
    """Build an exactly-80-char ENSDF G-record.
    eg  : Decimal (gamma energy)
    ri  : str (relative intensity, e.g. "100", "0.5", "99.0")
    dri : str ("1".."20", "LT", or "" for blank)
    q   : " " normal, "?" tentative
    """
    eg_str  = str(eg).ljust(10)[:10]   # cols 10-19
    de_str  = "  "                      # cols 20-21 (blank – no DE given)
    sp22    = " "                       # col  22  readability
    ri_str  = str(ri).ljust(7)[:7]     # cols 23-29
    dri_str = str(dri).ljust(2)[:2]    # cols 30-31
    rest    = " " * 48                  # cols 32-79
    line = NUCID + "  G " + eg_str + de_str + sp22 + ri_str + dri_str + rest + q
    if len(line) != 80:
        raise ValueError(f"len={len(line)}, expected 80:\n'{line}'")
    return line

