# -----------------------------------------------------------------------
# Generate and print
# -----------------------------------------------------------------------
for ei_raw, gammas in RAW:
    ei = Decimal(str(ei_raw))
    q  = "?" if ei in TENTATIVE else " "
    print(f"# Ei={ei}  Q='{q}'")

    # Sort by ascending Eg
    rows = []
    for ef_raw, ri, dri in gammas:
        ef = Decimal(str(ef_raw))
        eg = calc_eg(ei, ef)
        rows.append((eg, ri, dri))
    rows.sort()

    for eg, ri, dri in rows:
        line = make_g_record(eg, ri, dri, q)
        print(line)
    print()
